    "a": 1,
    "passage": "環境問題は工業化の進展と関係している。イギリス（UK）の、産業革命の時期に、化石燃料を動力源として利用する生産活動が本格的に始まった。その後、石炭や石油などの化石燃料の利用が増大したが、これは工業化の進展や経済成長に寄与する一方で、大気汚染や土壌汚染などを引き起こした。\n20世紀後半に国境を越えた汚染が広がると、こうした問題は国際社会の中で地球環境問題として関心を集めるようになった。国際連合総会（UN General Assembly）はこの課題に対応するため、1972年にスウェーデン（Sweden）の、ストックホルム（Stockholm）で国際会議を開催することを決定した。\n1997年に採択された京都議定書では、初めて先進国に具体的な、温室効果ガスの排出削減目標が課された。しかし、京都議定書ではBRICSなど成長著しい新興国には具体的な数値目標は課されなかった。発展途上国も含めたすべての締約国に排出削減の努力を求めた最初の国際的な取り決めは、2016年に発効したパリ協定（Paris Agreement）である。",
