    "passage": "よし子：⟦1:衆議院議員総選挙⟧について、「一票の格差」の問題が裁判で争われているというニュースを見ました。\n先生：「一票の格差」とは、選挙区間で議員一人当たりの有権者数に大きな違いがあることです。一票の格差があることで、投票価値の平等が損なわれるという問題が生じます。現在の日本では、衆議院の小選挙区選挙では最大で約2倍、参議院の選挙区選挙では最大で約3倍の一票の格差が生じています。こうした状態は、⟦2:日本国憲法が定める「法の下の平等」⟧に反するものではないかと、訴訟が起こされているのです。\nよし子：国会では区割りや定数の見直しなどが話し合われ、なんとか一票の格差を是正しようと努力していると報道されていました。\n先生：そうですね。例えば、各都道府県を一つの選挙区としていた参議院の選挙区選挙では、人口の少ない⟦3:高知県⟧と徳島県、鳥取県と島根県をそれぞれ一つの選挙区にするという「合区」が実施されました。\nよし子：なるほど、合区を増やして、人口に比例させて議席数を調整すれば、一票の格差は是正されますね。\n先生：はい。その通りです。しかし、それでは解決できない問題もあります。もし単純に有権者数に応じて議席数を定めると、人口の多い都市部から多くの政治家が選ばれることになります。⟦4:大企業が集中する都市部と過疎化が進む地方との経済格差⟧の問題を抱える日本にとってそのような状況は、さらなる格差の拡大を招く懸念があるのです。",
