    "passage": "⟦1:セメント⟧は，コンクリートやモルタルの材料として広範に用いられている。その主たる原料である石灰石は日本各地に分布しており，全国で200を超える石灰石鉱山が稼働している。\nセメントの歴史は古く，古代エジプト（Egypt）や古代ローマ（Rome）では既に建材として利用されていた。現在のように幅広い利用が始まったのは，産業革命期のイギリス（UK）においてである。この時期に，より短時間で固まるセメントの製法の開発が進んだ。日本では1875年に ⟦2:官営工場⟧で製造が開始され，1881年には初の民営セメント会社が，石灰石が豊富な山口県で誕生した。\n現在，日本のセメント産業は，電力業や鉄鋼業と同様に大量の温室効果ガスを排出しており，このことが大きな課題とされている。このため，⟦3:温室効果ガス排出削減⟧に向けてさまざまな研究開発が進められている。他方，石灰岩がある地域では ⟦4:カルスト地形⟧と呼ばれる独特の地形や景観が見られることがあり，重要な観光資源となっている場所も少なくない。日本最大級のカルスト地形が見られる山口県の秋吉台は，その地下約100mに秋芳洞と呼ばれる鍾乳洞が広がり，年間20万人を超える観光客を集めている。",
